package com.minecolonies.core.debug;

import com.minecolonies.core.entity.pathfinding.PathfindingUtils;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.fml.loading.FMLEnvironment;

public class DebugPlayerManager {
    private static Set<UUID> debugPlayers = new HashSet<UUID>();

    public static boolean hasDebugEnabled(Player player) {
        return !FMLEnvironment.production || debugPlayers.contains(player.m_20148_());
    }

    public static boolean toggleDebugModeFor(UUID player) {
        if (debugPlayers.contains(player)) {
            debugPlayers.remove(player);
            PathfindingUtils.trackingMap.remove(player);
            return false;
        }
        debugPlayers.add(player);
        return true;
    }

    public static void setDebugModeFor(UUID player, boolean enable) {
        if (!enable) {
            debugPlayers.remove(player);
        } else {
            debugPlayers.add(player);
        }
    }
}

